# Function to find symbol for address
find_symbol() {
    local addr=$1
    local symfile=$2
    # Find the largest symbol address <= target address
    awk -v target="$addr" '
    {
        if ($2 == "T" || $2 == "t" || $2 == "W" || $2 == "w") {
            if ("0x" $1 <= "0x" target) {
                # store candidate
                sym_addr = $1
                sym_name = $3
            }
        }
    }
    END { if (sym_name) print sym_addr, sym_name }
    ' "$symfile"
}

