import sys

def load_syms(path):
    syms = []
    with open(path) as f:
        for line in f:
            parts = line.strip().split()
            if len(parts) >= 3 and parts[1] in ('T','t','W','w','B','b','D','d'):
                syms.append((int(parts[0], 16), parts[2]))
    syms.sort()
    return syms

def lookup(syms, addr):
    best = None
    for (a, n) in syms:
        if a <= addr:
            best = (a, n)
        else:
            break
    if best:
        offset = addr - best[0]
        return f'{best[1]}+0x{offset:x}'
    return '???'

mono_syms = load_syms('symbols/mono_syms.txt')

addrs = [0x222098, 0x222234, 0x19bac0, 0x19bc14]
frames = ['#01', '#02', '#03', '#06']
for f, a in zip(frames, addrs):
    print(f'{f} pc {a:016x} -> {lookup(mono_syms, a)}')
"

