# The stripped binary has dynamic symbols. Let me check what functions are near these addresses more carefully.
# Let me try aarch64-linux-gnu-objdump to get all symbols including local PLT entries
# Actually let me try readelf for more complete symbol info
python3 -c "
import subprocess, re

# Get all symbols from .dynsym
result = subprocess.run(['aarch64-linux-gnu-readelf', '-W', '--syms', 'symbols/libmonosgen-2.0.so'], 
                      capture_output=True, text=True)

syms = []
for line in result.stdout.split('\n'):
    parts = line.split()
    if len(parts) >= 8:
        try:
            addr = int(parts[1], 16)
            size = int(parts[2])
            stype = parts[3]
            name = parts[7]
            if addr > 0 and stype == 'FUNC':
                syms.append((addr, size, name))
        except (ValueError, IndexError):
            pass

syms.sort()

def lookup(addr):
    for (a, sz, n) in syms:
        if a <= addr < a + sz:
            return f'{n}+0x{addr-a:x}'
    # fallback: find nearest
    best = None
    for (a, sz, n) in syms:
        if a <= addr:
            best = (a, sz, n)
        else:
            break
    if best:
        return f'{best[2]}+0x{addr-best[0]:x} (nearest, size={best[1]})'
    return '???'

addrs = [(0x222098, '#01'), (0x222234, '#02'), (0x19bac0, '#03'), (0x19bc14, '#06')]
for addr, frame in addrs:
    print(f'{frame} pc 0x{addr:08x} -> {lookup(addr)}')
" 2>&1

