result = subprocess.run(['aarch64-linux-gnu-readelf', '-W', '--syms', 'symbols/libmonosgen-2.0.so.dbg'], 
                      capture_output=True, text=True)

syms = []
for line in result.stdout.split('\n'):
    parts = line.split()
    if len(parts) >= 8:
        try:
            addr = int(parts[1], 16)
            size = int(parts[2])
            stype = parts[3]
            name = parts[7]
            if addr > 0 and stype == 'FUNC' and size > 0:
                syms.append((addr, size, name))
        except (ValueError, IndexError):
            pass

syms.sort()
print(f'Loaded {len(syms)} function symbols')

def lookup(addr):
    # Binary search for containing function
    lo, hi = 0, len(syms) - 1
    best = None
    while lo <= hi:
        mid = (lo + hi) // 2
        if syms[mid][0] <= addr:
            best = mid
            lo = mid + 1
        else:
            hi = mid - 1
    if best is not None:
        a, sz, n = syms[best]
        if a <= addr < a + sz:
            return f'{n}+0x{addr-a:x}'
        else:
            return f'{n}+0x{addr-a:x} (nearest)'
    return '???'

